+package com.example;
+
+import com.example.views.about.AboutView;
+import com.example.views.contact.ContactView;
+import com.vaadin.browserless.SpringBrowserlessTest;
+import com.vaadin.flow.component.Key;
+import com.vaadin.flow.component.button.Button;
+import com.vaadin.flow.component.dialog.Dialog;
+import com.vaadin.flow.component.grid.Grid;
+import com.vaadin.flow.component.html.H1;
+import com.vaadin.flow.component.notification.Notification;
+import com.vaadin.flow.router.RouterLink;
+import com.vaadin.flow.component.textfield.EmailField;
+import com.vaadin.flow.component.textfield.TextArea;
+import com.vaadin.flow.component.textfield.TextField;
+import org.junit.jupiter.api.Test;
+import org.springframework.boot.test.context.SpringBootTest;
+
+import static org.junit.jupiter.api.Assertions.assertEquals;
+import static org.junit.jupiter.api.Assertions.assertFalse;
+import static org.junit.jupiter.api.Assertions.assertTrue;
+
+@SpringBootTest
+class ContactViewBrowserlessTest extends SpringBrowserlessTest {
+
+    @Test
+    void contactViewHasHeadingLinkAndForm() {
+        ContactView view = navigate(ContactView.class);
+
+        assertEquals("Contact", $(H1.class).single().getText());
+        assertEquals("About", $(RouterLink.class).single().getText());
+
+        assertEquals("", $(TextField.class).withLabel("Name").single().getValue());
+        assertEquals("", $(EmailField.class).withLabel("Email").single().getValue());
+        assertEquals("", $(TextField.class).withLabel("Phone").single().getValue());
+        assertEquals("", $(TextArea.class).withLabel("Message").single().getValue());
+
+        Button send = $(Button.class).withText("Send").single();
+        assertTrue(send.isEnabled());
+    }
+
+    @Test
+    void emptyFormFailsValidationAndSendsNothing() {
+        navigate(ContactView.class);
+
+        int sizeBefore = test($(Grid.class).single()).size();
+
+        Button send = $(Button.class).withText("Send").single();
+        test(send).click();
+
+        TextField name = $(TextField.class).withLabel("Name").single();
+        EmailField email = $(EmailField.class).withLabel("Email").single();
+        TextArea message = $(TextArea.class).withLabel("Message").single();
+
+        assertTrue(name.isInvalid());
+        assertEquals("Name is required", name.getErrorMessage());
+
+        assertTrue(email.isInvalid());
+        assertEquals("Give an e-mail address or a phone number", email.getErrorMessage());
+
+        assertTrue(message.isInvalid());
+        assertEquals("Message is required", message.getErrorMessage());
+
+        assertEquals(sizeBefore, test($(Grid.class).single()).size());
+    }
+
+    @Test
+    void invalidEmailIsRejected() {
+        navigate(ContactView.class);
+
+        TextField name = $(TextField.class).withLabel("Name").single();
+        EmailField email = $(EmailField.class).withLabel("Email").single();
+        TextArea message = $(TextArea.class).withLabel("Message").single();
+
+        test(name).setValue("Jane");
+        test(email).setValue("not-an-email");
+        test(message).setValue("Hello there");
+
+        Button send = $(Button.class).withText("Send").single();
+        test(send).click();
+
+        assertTrue(email.isInvalid());
+        assertEquals("Enter a valid e-mail address", email.getErrorMessage());
+    }
+
+    @Test
+    void messageTooLongIsRejected() {
+        navigate(ContactView.class);
+
+        TextField name = $(TextField.class).withLabel("Name").single();
+        TextField phone = $(TextField.class).withLabel("Phone").single();
+        TextArea message = $(TextArea.class).withLabel("Message").single();
+
+        test(name).setValue("Jane");
+        test(phone).setValue("12345");
+        test(message).setValue("x".repeat(501));
+
+        Button send = $(Button.class).withText("Send").single();
+        test(send).click();
+
+        assertTrue(message.isInvalid());
+        assertEquals("Message must be at most 500 characters", message.getErrorMessage());
+    }
+
+    @Test
+    void phoneAloneIsEnoughToSend() {
+        navigate(ContactView.class);
+
+        Grid<?> grid = $(Grid.class).single();
+        int sizeBefore = test(grid).size();
+
+        TextField name = $(TextField.class).withLabel("Name").single();
+        TextField phone = $(TextField.class).withLabel("Phone").single();
+        TextArea message = $(TextArea.class).withLabel("Message").single();
+
+        test(name).setValue("Jane");
+        test(phone).setValue("12345");
+        test(message).setValue("Hello there");
+
+        Button send = $(Button.class).withText("Send").single();
+        test(send).click();
+
+        Notification notification = $(Notification.class).single();
+        assertTrue(test(notification).getText().contains("Message sent"));
+
+        assertEquals("", name.getValue());
+        assertEquals("", phone.getValue());
+        assertEquals("", message.getValue());
+
+        assertEquals(sizeBefore + 1, test(grid).size());
+
+        assertFalse(send.isEnabled());
+
+        test(name).setValue("Something");
+        assertTrue(send.isEnabled());
+    }
+
+    @Test
+    void sentMessageBecomesFirstGridRowAndSurvivesRenavigation() {
+        navigate(ContactView.class);
+
+        int sizeBefore = test($(Grid.class).single()).size();
+
+        test($(TextField.class).withLabel("Name").single()).setValue("Alice");
+        test($(TextField.class).withLabel("Phone").single()).setValue("111");
+        test($(TextArea.class).withLabel("Message").single()).setValue("First message");
+        test($(Button.class).withText("Send").single()).click();
+
+        navigate(ContactView.class);
+
+        test($(TextField.class).withLabel("Name").single()).setValue("Bob");
+        test($(TextField.class).withLabel("Phone").single()).setValue("222");
+        test($(TextArea.class).withLabel("Message").single()).setValue("Second message");
+        test($(Button.class).withText("Send").single()).click();
+
+        Grid<?> grid = $(Grid.class).single();
+        assertEquals(sizeBefore + 2, test(grid).size());
+        assertEquals("Bob", test(grid).getCellText(0, 0));
+        assertEquals("Alice", test(grid).getCellText(1, 0));
+
+        navigate(AboutView.class);
+        navigate(ContactView.class);
+
+        Grid<?> gridAgain = $(Grid.class).single();
+        assertEquals(sizeBefore + 2, test(gridAgain).size());
+    }
+
+    @Test
+    void enterKeySendsValidForm() {
+        navigate(ContactView.class);
+
+        test($(TextField.class).withLabel("Name").single()).setValue("Carol");
+        test($(TextField.class).withLabel("Phone").single()).setValue("333");
+        test($(TextArea.class).withLabel("Message").single()).setValue("Via enter key");
+
+        fireShortcut(Key.ENTER);
+
+        Notification notification = $(Notification.class).single();
+        assertTrue(test(notification).getText().contains("Message sent"));
+    }
+
+    @Test
+    void leavingWithDataAsksAndKeepEditingStays() {
+        navigate(ContactView.class);
+
+        test($(TextField.class).withLabel("Name").single()).setValue("Dana");
+
+        $(RouterLink.class).withText("About").single();
+        test($(RouterLink.class).withText("About").single()).click();
+
+        Dialog dialog = $(Dialog.class).single();
+        assertTrue(test(dialog).isUsable());
+
+        test($(Button.class).withText("Keep editing").single()).click();
+
+        assertEquals("Contact", $(H1.class).single().getText());
+        assertEquals("Dana", $(TextField.class).withLabel("Name").single().getValue());
+    }
+
+    @Test
+    void leavingWithDataAndDiscardingNavigatesAway() {
+        navigate(ContactView.class);
+
+        test($(TextField.class).withLabel("Name").single()).setValue("Erin");
+
+        test($(RouterLink.class).withText("About").single()).click();
+
+        test($(Button.class).withText("Discard").single()).click();
+
+        assertEquals("About", $(H1.class).single().getText());
+    }
+
+    @Test
+    void leavingWithEmptyFormDoesNotAsk() {
+        navigate(ContactView.class);
+
+        test($(RouterLink.class).withText("About").single()).click();
+
+        assertEquals("About", $(H1.class).single().getText());
+        assertFalse($(Dialog.class).exists());
+    }
+}
