+package com.example;
+
+import com.microsoft.playwright.Locator;
+import org.junit.jupiter.api.Test;
+import org.springframework.boot.test.context.SpringBootTest;
+import org.springframework.boot.test.web.server.LocalServerPort;
+import org.vaadin.addons.dramafinder.AbstractBasePlaywrightIT;
+import org.vaadin.addons.dramafinder.element.ButtonElement;
+import org.vaadin.addons.dramafinder.element.DialogElement;
+import org.vaadin.addons.dramafinder.element.EmailFieldElement;
+import org.vaadin.addons.dramafinder.element.GridElement;
+import org.vaadin.addons.dramafinder.element.NotificationElement;
+import org.vaadin.addons.dramafinder.element.TextAreaElement;
+import org.vaadin.addons.dramafinder.element.TextFieldElement;
+
+import static org.junit.jupiter.api.Assertions.assertEquals;
+import static org.junit.jupiter.api.Assertions.assertFalse;
+import static org.junit.jupiter.api.Assertions.assertTrue;
+
+@SpringBootTest(webEnvironment = SpringBootTest.WebEnvironment.RANDOM_PORT)
+class ContactViewPlaywrightTest extends AbstractBasePlaywrightIT {
+
+    @LocalServerPort
+    private int port;
+
+    @Override
+    public String getUrl() {
+        return "http://localhost:" + port;
+    }
+
+    @Test
+    void sendingValidMessageShowsNotificationAndAddsRow() {
+        page.navigate(getUrl() + "/contact");
+
+        assertEquals("Contact", page.locator("h1").innerText());
+
+        TextFieldElement.getByLabel(page, "Name").setValue("Playwright Pat");
+        TextFieldElement.getByLabel(page, "Phone").setValue("555-1234");
+        TextAreaElement.getByLabel(page, "Message").setValue("Hello from a real browser");
+
+        GridElement grid = GridElement.get(page);
+        int before = grid.getRenderedRowCount();
+
+        ButtonElement.getByText(page, "Send").click();
+
+        NotificationElement notification = NotificationElement.getByText(page, "Message sent");
+        notification.assertOpen();
+
+        assertEquals("", TextFieldElement.getByLabel(page, "Name").getValue());
+
+        grid.waitForGridToStopLoading();
+        assertEquals(before + 1, grid.getRenderedRowCount());
+
+        ButtonElement send = ButtonElement.getByText(page, "Send");
+        assertFalse(send.isEnabled());
+
+        TextFieldElement.getByLabel(page, "Name").setValue("x");
+        assertTrue(send.isEnabled());
+    }
+
+    @Test
+    void invalidFormShowsFieldErrors() {
+        page.navigate(getUrl() + "/contact");
+
+        ButtonElement.getByText(page, "Send").click();
+
+        TextFieldElement name = TextFieldElement.getByLabel(page, "Name");
+        name.assertInvalid();
+        name.assertErrorMessage("Name is required");
+
+        EmailFieldElement email = EmailFieldElement.getByLabel(page, "Email");
+        email.assertInvalid();
+        email.assertErrorMessage("Give an e-mail address or a phone number");
+    }
+
+    @Test
+    void leavingWithUnsavedDataShowsConfirmationDialog() {
+        page.navigate(getUrl() + "/contact");
+
+        TextFieldElement.getByLabel(page, "Name").setValue("Someone");
+
+        Locator aboutLink = page.getByText("About");
+        aboutLink.click();
+
+        DialogElement dialog = new DialogElement(page);
+        dialog.assertOpen();
+
+        ButtonElement.getByText(page, "Keep editing").click();
+        dialog.assertClosed();
+
+        assertEquals("Contact", page.locator("h1").innerText());
+
+        aboutLink.click();
+        dialog.assertOpen();
+        ButtonElement.getByText(page, "Discard").click();
+
+        Locator aboutHeading = page.locator("h1").getByText("About");
+        aboutHeading.waitFor();
+        assertEquals("About", aboutHeading.innerText());
+    }
+}
